/* ============================================================
   CommerceForge Dev Docs — Shared Styles
   Dark-mode-first, professional minimal design
   ============================================================ */

/* --- CSS Custom Properties (Dark Mode Default) --- */
:root {
  /* Backgrounds */
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --bg-card: #161b22;
  --bg-code: #1a1f29;
  --bg-overlay: rgba(13, 17, 23, 0.85);

  /* Borders */
  --border-default: #30363d;
  --border-subtle: #21262d;
  --border-accent: #475f9180;

  /* Text */
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --text-link: #7d9de0;
  --text-link-hover: #a4bdfc;

  /* Accent */
  --accent-primary: #475f91;
  --accent-secondary: #5b7ab8;
  --accent-cta: #00d4aa;
  --accent-cta-hover: #00e6b8;
  --accent-code: #7ee787;
  --accent-highlight: rgba(0, 212, 170, 0.12);

  /* Semantic */
  --color-success: #3fb950;
  --color-warning: #d29922;
  --color-error: #f85149;
  --color-info: #58a6ff;
  --color-comment: #8b949e;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.5);
  --shadow-cta: 0 0 24px rgba(0, 212, 170, 0.15);

  /* Layout */
  --sidebar-width: 260px;
  --sidebar-collapsed-width: 0px;
  --nav-height: 64px;
  --max-width: 1200px;
  --content-max-width: 860px;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.35rem;
  --font-size-2xl: 1.75rem;
  --font-size-3xl: 2.25rem;
  --font-size-4xl: 3rem;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-sidebar: 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* --- Light Mode Override --- */
[data-theme="light"] {
  --bg-primary: #ffffff;
  --bg-secondary: #f6f8fa;
  --bg-tertiary: #ebedf0;
  --bg-card: #ffffff;
  --bg-code: #f6f8fa;
  --bg-overlay: rgba(255, 255, 255, 0.85);

  --border-default: #d0d7de;
  --border-subtle: #e8eaed;
  --border-accent: #475f9140;

  --text-primary: #1f2328;
  --text-secondary: #656d76;
  --text-muted: #8c959f;
  --text-link: #475f91;
  --text-link-hover: #385380;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.06);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.1);
  --shadow-cta: 0 0 24px rgba(0, 212, 170, 0.2);
}

/* --- Reset & Base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

a {
  color: var(--text-link);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--text-link-hover);
}

img, svg {
  max-width: 100%;
  display: block;
}

code, pre, kbd {
  font-family: var(--font-mono);
}

/* --- Focus --- */
:focus-visible {
  outline: 2px solid var(--accent-cta);
  outline-offset: 2px;
}

/* --- Layout Utilities --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.container-sm {
  max-width: var(--content-max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-sm {
  padding: 48px 0;
}

.section-label {
  display: inline-block;
  font-size: var(--font-size-xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-cta);
  margin-bottom: 12px;
}

.section-title {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 16px;
  color: var(--text-primary);
}

.section-subtitle {
  font-size: var(--font-size-lg);
  color: var(--text-secondary);
  max-width: 680px;
  line-height: 1.65;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: var(--bg-overlay);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-default);
  display: flex;
  align-items: center;
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.nav-brand {
  font-weight: 700;
  font-size: var(--font-size-lg);
  color: var(--text-primary);
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav-brand-icon {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--accent-cta), var(--accent-primary));
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 18px;
  color: #fff;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-actions button {
  background: none;
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-sm);
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 6px;
}

.nav-actions button:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.nav-login {
  background: var(--bg-tertiary) !important;
  border-color: var(--bg-tertiary) !important;
  color: var(--text-primary) !important;
  font-weight: 500;
}

.nav-login:hover {
  background: var(--border-default) !important;
}

.nav-mobile-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 8px;
}

/* --- Hero --- */
.hero {
  padding: 100px 0 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(ellipse, var(--accent-highlight) 0%, transparent 70%);
  pointer-events: none;
  z-index: 0;
}

.hero-content {
  position: relative;
  z-index: 1;
}

.hero-title {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-cta) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: var(--font-size-lg);
  color: var(--text-secondary);
  max-width: 720px;
  margin: 0 auto 36px;
  line-height: 1.65;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  font-weight: 600;
  font-family: var(--font-sans);
  text-decoration: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: none;
  letter-spacing: -0.01em;
}

.btn-primary {
  background: var(--accent-cta);
  color: #0d1117;
  box-shadow: var(--shadow-cta);
}

.btn-primary:hover {
  background: var(--accent-cta-hover);
  transform: translateY(-1px);
  box-shadow: 0 0 32px rgba(0, 212, 170, 0.25);
  color: #0d1117;
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  background: var(--border-default);
  color: var(--text-primary);
}

.btn-ghost {
  background: transparent;
  color: var(--text-link);
  border: 1px solid transparent;
}

.btn-ghost:hover {
  background: var(--bg-tertiary);
  color: var(--text-link-hover);
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}

.card:hover {
  border-color: var(--border-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--accent-cta), var(--accent-primary));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  margin-bottom: 20px;
  color: #fff;
}

.card-title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}

.card-desc {
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 20px;
}

.card-link {
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--accent-cta);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: gap var(--transition-fast);
}

.card-link:hover {
  gap: 10px;
  color: var(--accent-cta-hover);
}

/* --- Grids --- */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* --- Product Cards (Home) --- */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: 40px 32px;
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent-cta), var(--accent-primary));
  opacity: 0;
  transition: opacity var(--transition-base);
}

.product-card:hover {
  border-color: var(--border-accent);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-card:hover::before {
  opacity: 1;
}

.product-card-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-lg);
  background: var(--bg-code);
  border: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 24px;
}

.product-card-title {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  margin-bottom: 12px;
  letter-spacing: -0.02em;
}

.product-card-desc {
  color: var(--text-secondary);
  font-size: var(--font-size-sm);
  line-height: 1.65;
  margin-bottom: 24px;
}

/* --- CLI Accordion (Home) --- */
.cli-section {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: 48px;
  margin-top: 40px;
}

.cli-header {
  text-align: center;
  margin-bottom: 36px;
}

.cli-header .section-title {
  font-size: var(--font-size-2xl);
}

.accordion {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-primary);
  transition: border-color var(--transition-fast);
}

.accordion-item.active {
  border-color: var(--border-accent);
}

.accordion-trigger {
  width: 100%;
  background: none;
  border: none;
  color: var(--text-primary);
  padding: 18px 24px;
  font-size: var(--font-size-lg);
  font-weight: 600;
  font-family: var(--font-sans);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  text-align: left;
  transition: background var(--transition-fast);
  letter-spacing: -0.01em;
}

.accordion-trigger:hover {
  background: var(--bg-secondary);
}

.accordion-chevron {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
  color: var(--text-muted);
}

.accordion-item.active .accordion-chevron {
  transform: rotate(180deg);
  color: var(--accent-cta);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.accordion-item.active .accordion-content {
  max-height: 500px;
}

.accordion-body {
  padding: 0 24px 24px;
}

.accordion-steps {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

.accordion-step {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.accordion-step-number {
  width: 28px;
  height: 28px;
  min-width: 28px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-xs);
  font-weight: 700;
  color: var(--text-secondary);
  margin-top: 1px;
}

.accordion-step-text {
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
  line-height: 1.6;
}

.accordion-step-text code {
  background: var(--bg-code);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.8em;
  color: var(--accent-code);
  border: 1px solid var(--border-subtle);
}

/* --- Code Blocks --- */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-default);
  background: var(--bg-tertiary);
}

.code-tab {
  padding: 10px 18px;
  font-size: var(--font-size-xs);
  font-weight: 600;
  font-family: var(--font-sans);
  border: none;
  background: none;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
  border-bottom: 2px solid transparent;
}

.code-tab:hover {
  color: var(--text-secondary);
}

.code-tab.active {
  color: var(--accent-cta);
  border-bottom-color: var(--accent-cta);
}

.code-content {
  padding: 20px 24px;
}

.code-content pre {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
  color: var(--text-primary);
  line-height: 1.7;
  overflow-x: auto;
}

.code-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  border-bottom: 1px solid var(--border-default);
}

.code-label {
  font-size: var(--font-size-xs);
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.code-copy {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: var(--font-size-xs);
  font-weight: 500;
  font-family: var(--font-sans);
  transition: color var(--transition-fast);
}

.code-copy:hover {
  color: var(--text-primary);
}

.code-inline {
  font-family: var(--font-mono);
  font-size: 0.88em;
  background: var(--bg-code);
  padding: 2px 7px;
  border-radius: 4px;
  color: var(--accent-code);
  border: 1px solid var(--border-subtle);
}

/* --- Sidebar Layout (interior pages) --- */
.page-layout {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  min-width: var(--sidebar-width);
  border-right: 1px solid var(--border-default);
  background: var(--bg-secondary);
  overflow-y: auto;
  height: calc(100vh - var(--nav-height));
  position: sticky;
  top: var(--nav-height);
  transition: all var(--transition-sidebar);
  padding: 24px 0;
}

.sidebar.collapsed {
  width: 0;
  min-width: 0;
  padding: 0;
  border-right: none;
  overflow: hidden;
}

.sidebar-inner {
  padding: 0 20px;
}

.sidebar-title {
  font-size: var(--font-size-xs);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 16px;
  padding: 0 8px;
}

.sidebar-nav {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sidebar-nav a {
  display: block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.sidebar-nav a:hover,
.sidebar-nav a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  margin-bottom: 20px;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-secondary);
  font-size: var(--font-size-xs);
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.main-content {
  flex: 1;
  min-width: 0;
  padding: 0;
}

.sidebar-toggle-fixed {
  position: fixed;
  left: 24px;
  bottom: 24px;
  z-index: 50;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-default);
  color: var(--text-primary);
  display: none;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: all var(--transition-fast);
}

.sidebar-toggle-fixed:hover {
  background: var(--border-default);
}

.sidebar.collapsed + .sidebar-toggle-fixed {
  display: flex;
}

/* --- Feature Lists (Grid Cards) --- */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition-base);
}

.feature-card:hover {
  border-color: var(--border-accent);
  box-shadow: var(--shadow-sm);
}

.feature-card-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--bg-code);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  margin-bottom: 16px;
}

.feature-card-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: 6px;
  letter-spacing: -0.01em;
}

.feature-card-desc {
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Launch CTA (Home) --- */
.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
