  }

  .sidebar {
    width: 240px;
    min-width: 240px;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .section {
    padding: 60px 0;
  }

  .hero {
    padding: 80px 0 60px;
  }

  .hero-title {
    font-size: var(--font-size-3xl);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
