  .grid-3,
  .product-cards,
  .feature-grid,
  .grid-2,
  .highlight-grid,
  .launch-grid,
  .tools-list,
  .how-it-works-grid,
  .process-flow {
    grid-template-columns: 1fr;
  }

  .grid-4,
  .community-grid,
  .actors-grid,
  .support-grid {
    grid-template-columns: 1fr;
  }

  .process-flow {
    flex-direction: column;
