  .sidebar.open {
    display: block;
  }

  .sidebar.collapsed {
    display: none;
  }

  .sidebar-toggle-fixed {
    display: flex;
  }

  .page-hero .container-sm {
    padding: 0 24px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .cli-section {
    padding: 32px 20px;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .btn {
    width: 100%;
    justify-content: center;
  }

  .section-title {
    font-size: var(--font-size-2xl);
  }

  .hero-title {
    font-size: var(--font-size-2xl);
  }
}

@media (max-width: 480px) {
  .container,
  .container-sm {
    padding: 0 16px;
  }

  .section {
    padding: 48px 0;
  }

  .hero {
    padding: 60px 0 48px;
  }

  .card,
  .product-card,
  .feature-card,
  .launch-card,
  .step-card,
  .tool-card {
    padding: 24px;
  }

  .code-content {
    padding: 16px;
  }

  .code-content pre {
    font-size: var(--font-size-xs);
  }
}

/* --- Print --- */
@media print {
  .nav,
  .sidebar,
  .sidebar-toggle-fixed,
  .footer {
    display: none;
  }

  body {
    background: #fff;
    color: #000;
  }
}

